slots=[(.23,.19),(.70,.19),(.28,.34),(.74,.34),(.20,.49),(.68,.49),(.27,.64),(.75,.64),(.24,.79),(.69,.79)]
briefs=[]
for district_id, keys, fact, visual, raw in rows:
    landmarks=[]
    for i,(pair,(x,y)) in enumerate(zip(raw.split('|'),slots)):
        name,note=pair.split('~')
        known=district_id=='new-halo' and name in ['The Shining Spire','The Soft Border']
        landmarks.append(dict(number=i+1,name=name,note=note,canonStatus='established name; proposed placement' if known else 'proposed',x=x,y=y))
    briefs.append(dict(id=district_id,sources=[sources[k] for k in keys.split()],establishedAnchor=fact,visualDirection=visual,landmarks=landmarks,status='provisional PDA expansion' if district_id=='crownless-row' else 'lore-grounded design candidate'))
