(root/'data/district-map-briefs.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
print(f'Prepared {len(briefs)} source-linked briefs and {sum(len(b["landmarks"]) for b in briefs)} annotated candidate locations.')
